import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv_transpose3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int64_t total_elements,
    int N,
    int IC,
    int ID,
    int IH,
    int IW,
    int OC,
    int OD,
    int OH,
    int OW,
    int KD,
    int KH,
    int KW,
    int stride_d,
    int stride_h,
    int stride_w,
    int pad_d,
    int pad_h,
    int pad_w,
    int groups,
    bool has_bias
) {
    // Register blocking: each thread computes two spatial outputs for one
    // output channel, while the CTA cooperatively stages the shared inputs.
    constexpr int TILE_SPATIAL = 128;
    constexpr int TILE_OC = 4;
    constexpr int K_TILE = 32;
    constexpr int THREADS = TILE_SPATIAL * TILE_OC / 2;
    (void)total_elements;
    extern __shared__ float smem[];
    float* __restrict__ sm_input = smem;
    float* __restrict__ sm_weight = smem + TILE_SPATIAL * K_TILE;
    const int tid = threadIdx.x;
    const int spatial_local = tid / TILE_OC;
    const int oc_local = tid % TILE_OC;
    const int spatial_size = OD * OH * OW;
    const int in_channels_per_group = IC / groups;
    const int out_channels_per_group = OC / groups;
    const int kernel_volume = KD * KH * KW;
    const int reduction_size = in_channels_per_group * kernel_volume;
    const int spatial_tiles = (spatial_size + TILE_SPATIAL - 1) / TILE_SPATIAL;
    const int oc_tiles = (out_channels_per_group + TILE_OC - 1) / TILE_OC;
    int block_id = static_cast<int>(blockIdx.x);
    const int oc_tile = block_id % oc_tiles;
    block_id /= oc_tiles;
    const int spatial_tile = block_id % spatial_tiles;
    block_id /= spatial_tiles;
    const int group = block_id % groups;
    const int n = block_id / groups;
    const int spatial_index0 = spatial_tile * TILE_SPATIAL + spatial_local;
    const int spatial_index1 = spatial_index0 + TILE_SPATIAL / 2;
    const int oc = group * out_channels_per_group + oc_tile * TILE_OC + oc_local;
    const bool valid_spatial0 = spatial_index0 < spatial_size;
    const bool valid_spatial1 = spatial_index1 < spatial_size;
    const bool valid_oc = oc_tile * TILE_OC + oc_local < out_channels_per_group;
    const bool valid_output0 = valid_spatial0 && n < N;
    const bool valid_output1 = valid_spatial1 && n < N;
    float acc0 = (valid_output0 && valid_oc && has_bias) ? bias[oc] : 0.0f;
    float acc1 = (valid_output1 && valid_oc && has_bias) ? bias[oc] : 0.0f;
    for (int k_base = 0; k_base < reduction_size; k_base += K_TILE) {
        // Map neighboring threads to neighboring spatial outputs so that
        // input loads are coalesced across the warp.
        for (int i = tid; i < TILE_SPATIAL * K_TILE; i += THREADS) {
            const int s = i % TILE_SPATIAL;
            const int k = k_base + (i / TILE_SPATIAL);
            float value = 0.0f;
            if (k < reduction_size) {
                const int ic_group = k / kernel_volume;
                int kernel_index = k % kernel_volume;
                const int kz = kernel_index / (KH * KW);
                kernel_index %= KH * KW;
                const int ky = kernel_index / KW;
                const int kx = kernel_index % KW;
                const int out_spatial = spatial_tile * TILE_SPATIAL + s;
                if (out_spatial < spatial_size) {
                    int tmp = out_spatial;
                    const int load_ow = tmp % OW;
                    tmp /= OW;
                    const int load_oh = tmp % OH;
                    tmp /= OH;
                    const int load_od = tmp;
                    const int id_numer = load_od + pad_d - kz;
                    const int ih_numer = load_oh + pad_h - ky;
                    const int iw_numer = load_ow + pad_w - kx;
                    if (id_numer >= 0 && ih_numer >= 0 && iw_numer >= 0 &&
                        id_numer % stride_d == 0 &&
                        ih_numer % stride_h == 0 &&
                        iw_numer % stride_w == 0) {
                        const int id = id_numer / stride_d;
                        const int ih = ih_numer / stride_h;
                        const int iw = iw_numer / stride_w;
                        if (id < ID && ih < IH && iw < IW) {
                            const int ic = group * in_channels_per_group + ic_group;
                            const int64_t input_idx =
                                (((static_cast<int64_t>(n) * IC + ic) * ID + id) * IH + ih) * IW + iw;
                            value = input[input_idx];
                        }
                    }
                }
            }
            sm_input[s * K_TILE + (i / TILE_SPATIAL)] = value;
        }
        for (int i = tid; i < TILE_OC * K_TILE; i += THREADS) {
            const int o = i / K_TILE;
            const int k = k_base + (i % K_TILE);
            float value = 0.0f;
            if (k < reduction_size &&
                oc_tile * TILE_OC + o < out_channels_per_group) {
                const int ic_group = k / kernel_volume;
                int kernel_index = k % kernel_volume;
                const int kz = kernel_index / (KH * KW);
                kernel_index %= KH * KW;
                const int ky = kernel_index / KW;
                const int kx = kernel_index % KW;
                const int ic = group * in_channels_per_group + ic_group;
                const int oc_local_group = oc_tile * TILE_OC + o;
                const int64_t weight_idx =
                    ((((static_cast<int64_t>(ic) * out_channels_per_group + oc_local_group) * KD + kz)
                      * KH + ky) * KW + kx);
                value = weight[weight_idx];
            }
            sm_weight[o * K_TILE + (i % K_TILE)] = value;
        }
        __syncthreads();
        if (valid_oc && (valid_output0 || valid_output1)) {
            const int valid_k = min(K_TILE, reduction_size - k_base);
            for (int kk = 0; kk < valid_k; ++kk) {
                const float w = sm_weight[oc_local * K_TILE + kk];
                if (valid_output0) {
                    acc0 += sm_input[spatial_local * K_TILE + kk] * w;
                }
                if (valid_output1) {
                    acc1 += sm_input[(spatial_local + TILE_SPATIAL / 2) * K_TILE + kk] * w;
                }
            }
        }
        __syncthreads();
    }
    if (valid_output0 && valid_oc) {
        int t = spatial_index0;
        const int ow = t % OW;
        t /= OW;
        const int oh = t % OH;
        const int od = t / OH;
        const int64_t output_idx =
            (((static_cast<int64_t>(n) * OC + oc) * OD + od) * OH + oh) * OW + ow;
        output[output_idx] = acc0;
    }
    if (valid_output1 && valid_oc) {
        int t = spatial_index1;
        const int ow = t % OW;
        t /= OW;
        const int oh = t % OH;
        const int od = t / OH;
        const int64_t output_idx =
            (((static_cast<int64_t>(n) * OC + oc) * OD + od) * OH + oh) * OW + ow;
        output[output_idx] = acc1;
    }
}

torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_d,
    int stride_h,
    int stride_w,
    int pad_d,
    int pad_h,
    int pad_w,
    int output_pad_d,
    int output_pad_h,
    int output_pad_w,
    int groups
) {
    TORCH_CHECK(input.is_cuda(), "input must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(weight.scalar_type() == torch::kFloat32, "weight must be float32");
    TORCH_CHECK(input.dim() == 5, "input must have shape [N, C, D, H, W]");
    TORCH_CHECK(weight.dim() == 5, "weight must have shape [C_in, C_out/groups, Kd, Kh, Kw]");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");
    TORCH_CHECK(groups > 0, "groups must be positive");

    const int N = static_cast<int>(input.size(0));
    const int IC = static_cast<int>(input.size(1));
    const int ID = static_cast<int>(input.size(2));
    const int IH = static_cast<int>(input.size(3));
    const int IW = static_cast<int>(input.size(4));

    TORCH_CHECK(IC % groups == 0, "input channels must be divisible by groups");
    TORCH_CHECK(weight.size(0) == IC, "weight input-channel dimension mismatch");

    const int OC_per_group = static_cast<int>(weight.size(1));
    const int OC = OC_per_group * groups;

    const int KD = static_cast<int>(weight.size(2));
    const int KH = static_cast<int>(weight.size(3));
    const int KW = static_cast<int>(weight.size(4));

    TORCH_CHECK(output_pad_d < stride_d, "output_padding depth must be smaller than stride");
    TORCH_CHECK(output_pad_h < stride_h, "output_padding height must be smaller than stride");
    TORCH_CHECK(output_pad_w < stride_w, "output_padding width must be smaller than stride");

    const int OD = (ID - 1) * stride_d - 2 * pad_d + KD + output_pad_d;
    const int OH = (IH - 1) * stride_h - 2 * pad_h + KH + output_pad_h;
    const int OW = (IW - 1) * stride_w - 2 * pad_w + KW + output_pad_w;

    auto output = torch::empty(
        {N, OC, OD, OH, OW},
        input.options()
    );

    const bool has_bias = bias.numel() != 0;
    if (has_bias) {
        TORCH_CHECK(bias.is_cuda(), "bias must be CUDA");
